using Microsoft.SemanticKernel;
using Microsoft.SemanticKernel.Embeddings;

// 1. Register embedding service in Kernel builder
var kernel = Kernel.CreateBuilder()
    .AddAzureOpenAITextEmbeddingGeneration("text-embedding-3-small", endpoint, credential)
    .Build();

var embeddingService = kernel.GetRequiredService<ITextEmbeddingGenerationService>();

// 2. Generate embeddings for a collection of document chunks
var documents = new List<string>
{
    "Azure Kubernetes Service supports automated cluster node scaling.",
    "Cosmos DB multi-region replication ensures low latency worldwide.",
    "Azure API Management acts as a reverse proxy and AI gateway."
};

IList<ReadOnlyMemory<float>> embeddings = await embeddingService.GenerateEmbeddingsAsync(documents);

Console.WriteLine($"Generated {embeddings.Count} embeddings. Dimension: {embeddings[0].Length}");

public class KnowledgeBasePlugin
{
    private readonly IVectorStoreRecordCollection<string, KnowledgeChunkRecord> _collection;
    private readonly ITextEmbeddingGenerationService _embeddingService;

    public KnowledgeBasePlugin(
        IVectorStore vectorStore,
        ITextEmbeddingGenerationService embeddingService)
    {
        _collection = vectorStore.GetCollection<string, KnowledgeChunkRecord>("enterprise_kb");
        _embeddingService = embeddingService;
    }

    [KernelFunction("search_knowledge_base")]
    [Description("Searches corporate architecture documentation and guidelines for answers to technical questions.")]
    public async Task<List<string>> SearchAsync(
        [Description("The search query or concept")] string query,
        CancellationToken ct = default)
    {
        var embedding = await _embeddingService.GenerateEmbeddingAsync(query, cancellationToken: ct);
        var results = new List<string>();

        await foreach (var record in _collection.VectorizedSearchAsync(embedding, new VectorSearchOptions<KnowledgeChunkRecord> { Top = 3 }, ct))
        {
            results.Add(record.Record.Content);
        }

        return results;
    }
}
